const messages = $input.all();

const conversation = messages
  .reverse()
  .map(item => `user: ${item.json.context}`)
  .join('\n');

const question = $('Telegram Trigger').first().json.message?.text ?? '';

return [
  {
    json: {
      conversation,
      question
    }
  }
];

const message = ($json.question || "").trim().toLowerCase();

const orderKeywords = [
  "order",
  "order dite chai",
  "order dibo",
  "order krte chai",
  "order korbo",
  "অর্ডার",
  "অর্ডার দিতে চাই",
  "অর্ডার দিব",
  "অর্ডার করবো"
];

const hasOrderKeyword = orderKeywords.some(keyword =>
  message.includes(keyword)
);

const hasOrderFields =
  message.includes("name:") &&
  message.includes("phone:") &&
  message.includes("address:") &&
  message.includes("product:") &&
  message.includes("quantity:");

let intent = "chat";

if (hasOrderFields) {
  intent = "order_details";
} else if (hasOrderKeyword) {
  intent = "order_request";
}

return [
  {
    json: {
      intent,
      message
    }
  }
];

const message = $json.message || "";

function getField(name) {
  const regex = new RegExp(`^${name}:\\s*(.*)$`, "im");
  const match = message.match(regex);
  return match ? match[1].trim() : "";
}

const customer_name = getField("Name");
const phone = getField("Phone");
const address = getField("Address");
const product = getField("Product");
const quantityText = getField("Quantity");
const paymentText = getField("Payment");

const quantity = Number(quantityText) || 1;

const payment_method =
  paymentText.toLowerCase() === "bkash"
    ? "bkash"
    : "cod";

return [
  {
    json: {
      customer_name,
      phone,
      address,
      product,
      quantity,
      payment_method,
    }
  }
];

const items = $input.all();

const products = new Map();

for (const item of items) {
  const product = item.json;

  // Out of stock product বাদ
  if (Number(product.stock) <= 0) {
    continue;
  }

  if (!products.has(product.id)) {
    products.set(product.id, {
      ...product,
      textMatch: false,
      vectorDistance: null,
    });
  }

  const current = products.get(product.id);

  if (product.distance !== undefined) {
    current.vectorDistance = product.distance;
  } else {
    current.textMatch = true;
  }
}

const candidates = Array.from(products.values());

candidates.sort((a, b) => {
  if (a.textMatch !== b.textMatch) {
    return a.textMatch ? -1 : 1;
  }

  if (a.vectorDistance === null) return 1;
  if (b.vectorDistance === null) return -1;

  return a.vectorDistance - b.vectorDistance;
});

if (candidates.length === 0) {
  return [
    {
      json: {
        matched: false,
        reason: "out_of_stock_or_not_found"
      }
    }
  ];
}

return [
  {
    json: {
      matched: true,
      ...candidates[0]
    }
  }
];

